$error = null;$id=(int)($_GET['id']??$_POST['id']??0);$q=$dbh->prepare('SELECT id,username,full_name FROM teachers WHERE id=:id');$q->execute([':id'=>$id]);$t=$q->fetch();if(!$t)exit('Teacher not found.');$msg='';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$p=$_POST['password']??'';if(strlen($p)<8)$error='Password must be at least 8 characters.';else{$u=$dbh->prepare('UPDATE teachers SET password=:p,updated_at=NOW() WHERE id=:id');$u->execute([':p'=>password_hash($p,PASSWORD_DEFAULT),':id'=>$id]);audit_log($dbh,'TEACHER_PASSWORD_RESET','Reset password for '.$t['username']);$msg='Password reset successfully.';}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reset Teacher Password</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><main class="main-page"><div class="container srms-page"><a href="manage-teachers.php" class="btn btn-default">← Teachers</a><div class="panel m-t-20"><div class="panel-heading"><h3>Reset Password: <?php echo e($t['full_name']);?></h3></div><div class="panel-body"><?php if($msg):?><div class="alert alert-success"><?php echo e($msg);?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?php echo e($error);?></div><?php endif;?><form method="post"><?php echo csrf_field();?><input type="hidden" name="id" value="<?php echo $id;?>"><div class="form-group"><label>New Password</label><input class="form-control" type="password" name="password" minlength="8" required></div><button class="btn btn-warning">Reset Password</button></form></div></div></div></main></div></div></div></